#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define ADS1115_ADDR 0x48
#define ADS1115_CONVERT 0x84

int main() {
    int file_i2c;
    char *filename = (char*)"/dev/i2c-1";
    int addr = ADS1115_ADDR;

    if ((file_i2c = open(filename, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, addr) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    while (1) {
        char buffer[2] = {0};
        buffer[0] = ADS1115_CONVERT;
        if (write(file_i2c, buffer, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
        }

        usleep(800000);  // Wait for conversion to complete

        if (read(file_i2c, buffer, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
        } else {
            int value = (buffer[0] << 8) | buffer[1];
            printf("ADC value: %d\n", value);
        }

        sleep(0.5);
    }

    close(file_i2c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <wiringPi.h>

#define MLX90614_ADDR 0x5a
#define MLX90614_TOBJ1 0x07

int fd;

void setup() {
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the i2c bus.\n");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access or talk to slave.\n");
        exit(1);
    }
}

float readTemp() {
    unsigned char buffer[2];

    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from the i2c bus.\n");
        exit(1);
    }

    float temp = (buffer[0] << 8) | buffer[1];
    return temp * 0.02 - 273.15; // Convert to Celsius
}

void cleanup() {
    close(fd);
}

int main() {
    setup();

    while (1) {
        float temp = readTemp();
        printf("Temperature: %.2f C\n", temp);
        sleep(5);
    }

    cleanup();
    return 0;
}

