#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 500

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the GPIO mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Start the PWM output
    if (gpioStartPWM(GPIO_PIN, PWM_FREQ, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("PWM output started on GPIO %d\n", GPIO_PIN);

    // Wait for user interrupt
    while (1)
    {
        sleep(0.5);
    }

    // Cleanup
    gpioStopPWM(GPIO_PIN);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_TRIG 17
#define GPIO_ECHO 27
#define MAX_DISTANCE 400 // Maximum distance in cm

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int request_flags = 0;
    int value;
    long long timeout_ns;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed\n");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIG);
    if (!trig) {
        perror("Get line failed\n");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo) {
        perror("Get line failed\n");
        return 1;
    }

    if (gpiod_line_request_output(trig, "trigger", 0) < 0) {
        perror("Request line as output failed\n");
        return 1;
    }

    if (gpiod_line_request_input(echo, "echo") < 0) {
        perror("Request line as input failed\n");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        timeout_ns = gpiod_line_event_wait(echo, 1000000000);
        if (timeout_ns <= 0) {
            printf("Timeout\n");
            continue;
        }

        gpiod_line_event_read(echo, &value, &timeout_ns);
        if (timeout_ns <= 0) {
            printf("Timeout\n");
            continue;
        }

        printf("Distance: %d cm\n", value * MAX_DISTANCE / 1000000);
        sleep(60);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

