#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_LINE 17

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    chip = gpiod_chip_open(GPIO_DEVICE);
    if (chip == NULL) {
        perror("Open chip failed\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("Get line failed\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "gpio-example", 0) < 0) {
        perror("Request line as output failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set GPIO to HIGH
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Set line value failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Read the GPIO value and print it
    value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Get line value failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    printf("GPIO %d value: %d\n", GPIO_LINE, value);

    // Set GPIO to LOW
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Set line value failed\n");
        gpiod_line_release(line);
