#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define DEVICE_ADDR 0x40
#define DEVICE_FILE "/dev/i2c-1"

int main() {
    int file_i2c;
    int length;
    unsigned char buffer[2];

    // Open I2C device
    if ((file_i2c = open(DEVICE_FILE, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    // Set the I2C slave address
    if (ioctl(file_i2c, I2C_SLAVE, DEVICE_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    // Read measurements from the sensor
    while (1) {
        // Send measurement command
        buffer[0] = 0x2C;  // command to start measurement
        length = 1;
        if (write(file_i2c, buffer, length) != length) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }

        // Wait for measurement to complete
        usleep(200000);  // 200ms delay

        // Read measurements
        buffer[0] = 0x00;  // start from address 0
        length = 2;
        if (write(file_i2c, buffer, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }
        if (read(file_i2c, buffer, length) != length) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        // Convert measurements to degrees Celsius and relative humidity
        float humidity = ((buffer[0] * 256 + buffer[1]) * 125 / 65536.0) - 6;
        float cTemp = humidity;
        float fTemp = cTemp * 9.0 / 5.0 + 32;

        // Print measurements
        printf("Humidity: %.2f %%\n", humidity);
        printf("Temperature: %.2f C (%.2f F)\n", cTemp, fTemp);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(file_i2c);

    return 0;
}

#include <stdio.h>
