#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define ADS1115_ADDR 0x48
#define ADS1115_CONVERT 0x84

int main() {
    int file_i2c;
    char *filename = (char*)"/dev/i2c-1";
    if ((file_i2c = open(filename, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, ADS1115_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    char buf[2] = {0};
    for (int i = 0; i < 3; i++) {
        buf[0] = ADS1115_CONVERT;
        if (write(file_i2c, buf, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }

        usleep(1000000);  // Wait for conversion to complete

        if (read(file_i2c, buf, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        int value = (buf[0] << 8) | buf[1];
        printf("ADC value: %d\n", value);
        usleep(1000000);  // Wait for 1 second
    }

    close(file_i2c);
    return 0;
}

