#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN1 2
#define GPIO_PIN2 3
#define GPIO_PIN3 18

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the GPIO pins as output
    gpioSetMode(GPIO_PIN1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN2, PI_OUTPUT);
    gpioSetMode(GPIO_PIN3, PI_OUTPUT);

    // Start the PWM on the GPIO pins
    gpioPWM(GPIO_PIN1, 500);
    gpioPWM(GPIO_PIN2, 500);
    gpioPWM(GPIO_PIN3, 500);

    // Main loop
    while (1)
    {
        // Print the state of the GPIO pins
        printf("GPIO %d: %d\n", GPIO_PIN1, gpioRead(GPIO_PIN1));
        printf("GPIO %d: %d\n", GPIO_PIN2, gpioRead(GPIO_PIN2));
        printf("GPIO %d: %d\n", GPIO_PIN3, gpioRead(GPIO_PIN3));

        // Wait for 0.15 seconds
        time_sleep(0.15);
    }

    // Cleanup
    gpioPWM(GPIO_PIN1, 0);
    gpioPWM(GPIO_PIN2, 0);
    gpioPWM(GPIO_PIN3, 0);
    gpioTerminate();

    return 0;
}

