#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>

#define I2C_DEV_PATH "/dev/i2c-1"
#define OPT3001_ADDR 0x44

int main() {
    int file_i2c;
    unsigned char buffer[2];
    float lux;

    if ((file_i2c = open(I2C_DEV_PATH, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, OPT3001_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    buffer[0] = 0x00;  // Configuration register
    if (write(file_i2c, buffer, 1) != 1) {
        printf("Failed to write to the i2c bus\n");
        exit(1);
    }

    if (read(file_i2c, buffer, 2) != 2) {
        printf("Failed to read from the i2c bus\n");
        exit(1);
    }

    // Convert the data to lux
    lux = ((buffer[0] * 256) + buffer[1]) * 0.01;

    printf("Lux: %f\n", lux);

    close(file_i2c);
    return 0;
}

