#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN1 4
#define GPIO_PIN2 12
#define GPIO_PIN3 18

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the GPIO modes
    gpioSetMode(GPIO_PIN1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN2, PI_OUTPUT);
    gpioSetMode(GPIO_PIN3, PI_OUTPUT);

    // Start the PWM on the pins
    gpioPWM(GPIO_PIN1, 500); // 500Hz
    gpioPWM(GPIO_PIN2, 500); // 500Hz
    gpioPWM(GPIO_PIN3, 500); // 500Hz

    // Main loop
    while (1)
    {
        // Write to the GPIO pins
        gpioWrite(GPIO_PIN1, 1);
        gpioWrite(GPIO_PIN2, 1);
        gpioWrite(GPIO_PIN3, 1);

        // Wait for 1 second
        time_sleep(1);

        // Write to the GPIO pins
        gpioWrite(GPIO_PIN1, 0);
        gpioWrite(GPIO_PIN2, 0);
        gpioWrite(GPIO_PIN3, 0);

        // Wait for 1 second
        time_sleep(1);
    }

    // Cleanup the library
    gpioTerminate();

    return 0;
}

