#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PWM1 17
#define GPIO_PWM2 18
#define GPIO_PWM3 27

volatile sig_atomic_t stop;

void intHandler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, intHandler);

    gpioSetMode(GPIO_PWM1, PI_OUTPUT);
    gpioSetMode(GPIO_PWM2, PI_OUTPUT);
    gpioSetMode(GPIO_PWM3, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_PWM1, 1000);
    gpioSetPWMfrequency(GPIO_PWM2, 1000);
    gpioSetPWMfrequency(GPIO_PWM3, 1000);

    int dutyCycle = 0;
    int direction = 1;

    while (!stop) {
        gpioPWM(GPIO_PWM1, 0, 1000);
        gpioPWM(GPIO_PWM2, 0, 1000);
        gpioPWM(GPIO_PWM3, 0, 1000);

        printf("PWM signals are off\n");

        sleep(5);

        gpioPWM(GPIO_PWM1, dutyCycle, 1000);
        gpioPWM(GPIO_PWM2, dutyCycle, 1000);
        gpioPWM(GPIO_PWM3, dutyCycle, 1000);

        printf("PWM signals are on\n");

        sleep(5);

        dutyCycle += 1000;
        if (dutyCycle > 2000) {
            dutyCycle = 0;
        }
    }

    gpioTerminate();

    return 0;
}

