#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>

#define ADXL345_DEVICE_ADDR 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

int main() {
    int file_i2c;
    int length = 1;
    char buffer[16];

    if ((file_i2c = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, ADXL345_DEVICE_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    // Enable measurements
    buffer[0] = ADXL345_POWER_CTL;
    buffer[1] = 0x08;
    if (write(file_i2c, buffer, length) != length) {
        printf("Failed to write to the i2c bus\n");
        exit(1);
    }

    while (1) {
        buffer[0] = ADXL345_DATAX0;
        if (write(file_i2c, buffer, length) != length) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }

        if (read(file_i2c, buffer, 6) != 6) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        printf("X: %d, Y: %d, Z: %d\n", buffer[1], buffer[3], buffer[5]);
        usleep(100000);  // Sleep for 0.1 seconds
    }

    close(file_i2c);
    return 0;
}

