#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PWM_1 17
#define GPIO_PWM_2 22
#define GPIO_PWM_3 27

#define PWM_FREQ 500
#define PWM_DUTYCYCLE 0

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set the GPIO modes
    gpioSetMode(GPIO_PWM_1, PI_OUTPUT);
    gpioSetMode(GPIO_PWM_2, PI_OUTPUT);
    gpioSetMode(GPIO_PWM_3, PI_OUTPUT);

    // Start the PWM
    gpioPWM(GPIO_PWM_1, PWM_FREQ, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PWM_2, PWM_FREQ, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PWM_3, PWM_FREQ, PWM_DUTYCYCLE);

    while (1)
    {
        // Increase the duty cycle
        for (int i = 0; i < 100; i++)
        {
            gpioPWM(GPIO_PWM_1, PWM_FREQ, i * 1000);
            gpioPWM(GPIO_PWM_2, PWM_FREQ, i * 1000);
            gpioPWM(GPIO_PWM_3, PWM_FREQ, i * 1000);
            time_sleep(0.5);
        }

        // Decrease the duty cycle
        for (int i = 100; i > 0; i--)
        {
            gpioPWM(GPIO_PWM_1, PWM_FREQ, i * 1000);
            gpioPWM(GPIO_PWM_2, PWM_FREQ, i * 1000);
            gpioPWM(GPIO_PWM_3, PWM_FREQ, i * 1000);
            time_sleep(0.5);
        }
    }

    // Cleanup
    gpioPWM(GPIO_PWM_1, 0, 0);
    gpioPWM(GPIO_PWM_2, 0, 0);
    gpioPWM(GPIO_PWM_3, 0, 0);
    gpioTerminate();

    return 0;
}

