#define I2C_ADDR 0x29 // I2C address of the TCS34725
#define DEVICE "/dev/i2c-1" // I2C device file

int main() {
    int file_i2c = open(DEVICE, O_RDWR);
    if (file_i2c < 0) {
        printf("Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file_i2c, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        return 1;
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        printf("Failed to initialize the GPIO library\n");
        return 1;
    }

    // Set the TCS34725 to command mode
    gpioWrite(23, 0);
    gpioDelay(1);

    // Set the TCS34725 to read mode
    gpioWrite(23, 1);
    gpioDelay(1);

    while (1) {
        char reg = 0x14;
        write(file_i2c, &reg, 1);

        char data[8] = {0};
        if (read(file_i2c, data, 8) != 8) {
            printf("Failed to read from the i2c bus\n");
            return 1;
        }

        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n", data[1]<<8 | data[0], data[3]<<8 | data[2], data[5]<<8 | data[4], data[7]<<8 | data[6]);

        sleep(0.2);
    }

    // Release the GPIO library
    gpioTerminate();

    return 0;
}

