#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int camera_fd, image_fd;
    unsigned char *buffer;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;

    // Open camera device
    if ((camera_fd = open(CAMERA_DEVICE, O_RDWR)) < 0) {
        perror("Cannot open camera device");
        return 1;
    }

    // Set image format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Cannot set image format");
        return 1;
    }

    // Request buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(camera_fd, VIDIOC_REQBUFS, &buf) < 0) {
        perror("Cannot request buffer");
        return 1;
    }

    // Open image file
    if ((image_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Cannot open image file");
        return 1;
    }

    // Capture image
    if (ioctl(camera_fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Cannot start capturing");
        return 1;
    }
    read(camera_fd, buffer, fmt.fmt.pix.sizeimage);
    write(image_fd, buffer, fmt.fmt.pix.sizeimage);
    ioctl(camera_fd, VIDIOC_STREAMOFF, &buf.type);

    // Clean up
    close(image_fd);
    close(camera_fd);

    return 0;
}

