#define GPIO_PWM_11 11
#define GPIO_PWM_18 18

#define PWM_FREQUENCY 1000
#define PWM_DUTYCYCLE 500

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

