    gpioSetPWMfrequency(GPIO_PWM_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_PWM_9, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_PWM_11, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_PWM_18, PWM_FREQUENCY);

    // Set the PWM duty cycle for all GPIOs
    gpioSetPWMdutycycle(GPIO_PWM_8, PWM_DUTYCYCLE);
    gpioSetPWMdutycycle(GPIO_PWM_9, PWM_DUTYCYCLE);
    gpioSetPWMdutycycle(GPIO_PWM_11, PWM_DUTYCYCLE);
    gpioSetPWMdutycycle(GPIO_PWM_18, PWM_DUTYCYCLE);

    // Start the PWM output for all GPIOs
    gpioPWM(GPIO_PWM_8, PWM_FREQUENCY, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PWM_9, PWM_FREQUENCY, PWM_DUTYCYCLE);
