        if (file == NULL) {
            perror("Failed to open file for writing");
            return 1;
        }
        fwrite(buf.m.userptr, 1, buf.bytesused, file);
        fclose(file);

        // Re-enqueue the buffer
        if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to re-enqueue buffer");
            return 1;
        }

        // Sleep for the specified delay
        usleep(CAPTURE_DELAY);
    }

    // Cleanup
    ioctl(camera_fd, VIDIOC_STREAMOFF, &fmt.type);
    close(camera_fd);

    return 0;
}

#include <stdio.h>
