#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <bme280.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BME280_ADDR 0x76

int main() {
    int fd;
    struct bme280_dev dev;
    struct bme280_data comp_data;

    // Initialize I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    // Initialize BME280 device
    dev.dev_id = BME280_ADDR;
    dev.intf = BME280_I2C_INTF;
    dev.read = bme280_i2c_read;
    dev.write = bme280_i2c_write;
    dev.delay_us = bme280_delay_us;
    dev.intf_ptr = &fd;

    if (bme280_init(&dev) != BME280_OK) {
        perror("Failed to initialize the bme280\n");
        exit(1);
    }

    // Set the sensor settings
    struct bme280_config conf;
    bme280_get_sensor_settings(&conf, &dev);
    conf.filter = BME280_FILTER_OFF;
    conf.standby_time = BME280_STANDBY_TIME_62_5_MS;
    conf.osr_h = BME280_OVERSAMPLING_16X;
    conf.osr_p = BME280_OVERSAMPLING_16X;
    conf.osr_t = BME280_OVERSAMPLING_2X;
    bme280_set_sensor_settings(&conf, &dev);

    // Main loop
    while (1) {
        if (bme280_set_sensor_mode(BME280_FORCED_MODE, &dev) != BME280_OK) {
            perror("Failed to set sensor mode\n");
            exit(1);
        }

        // Wait for measurement to complete
        bme280_delay_us(7000, dev.intf_ptr);

        // Read data
        if (bme280_get_sensor_data(&comp_data, &dev) != BME280_OK) {
            perror("Failed to get sensor data\n");
            exit(1);
        }

        // Print data
        printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f%%\n",
               comp_data.temperature / 100.0, comp_data.pressure / 100.0, comp_data.humidity / 100.0);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(fd);

    return 0;
}

