// Function to write to the LCD
void lcd_byte(int bits, int mode) {
    int bits_high;
    int bits_low;

    // Use the HAL function to send bits
    bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    i2c_smbus_write_byte(file_i2c, bits_high);
    lcd_toggle_enable(file_i2c);

    // Low bits
    i2c_smbus_write_byte(file_i2c, bits_low);
    lcd_toggle_enable(file_i2c);
}

// Function to toggle the enable pin on the LCD
void lcd_toggle_enable(int file_i2c) {
    usleep(500);
    i2c_smbus_write_byte(file_i2c, 0x00);
    usleep(500);
}

// Function to initialize the LCD
void lcd_init(int file_i2c) {
    lcd_byte(0x33, LCD_CMD); // Initialization
    lcd_byte(0x32, LCD_CMD); // Initialization
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn cursor off
    lcd_byte(0x28, LCD_CMD); // 2 line, 5x7 matrix
    lcd_byte(0x01, LCD_CMD); // Clear display
    usleep(2000);
}

