#define SENSOR_PIN 7 // Change this to the pin where your sensor is connected
#define MQTT_BROKER "tcp://mqtt.eclipse.org:1883" // Change this to your MQTT broker
#define MQTT_CLIENTID "sensor_publisher"
#define MQTT_TOPIC "sensors/sensor_reading" // Change this to your topic

int readSensor();
void publish(int reading);

int main() {
    if (wiringPiSetup() == -1) {
        printf("Failed to setup wiringPi\n");
        return 1;
    }

    int reading;
    while (1) {
        reading = readSensor();
        if (reading != -1) {
            publish(reading);
        }
        delay(10); // Delay for 0.01 seconds
    }

    return 0;
}

int readSensor() {
    // Implement your sensor reading logic here
    // Return -1 if the reading is invalid
    return rand() % 1024; // Replace this with your sensor reading logic
}

void publish(int reading) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        printf("Failed to connect to MQTT broker: %d\n", rc);
        return;
    }

    pubmsg.payload = (void*) &reading;
    pubmsg.payloadlen = sizeof(reading);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    printf("Waiting for up to %d seconds for publication of %s\n"
            "on topic %s for client with ClientID: %s\n",
            (int)(1000/conn_opts.keepAliveInterval), pubmsg.payload,
            MQTT_TOPIC, MQTT_CLIENTID);
    rc = MQTTClient_waitForCompletion(client, token, 1000L);
    printf("Message with delivery token %d delivered\n", token);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
}

