#define ADDRESS     "your_broker_address"
#define CLIENTID    "your_client_id"
#define TOPIC       "your_topic"
#define PAYLOAD     "your_payload"
#define QOS         1
#define TIMEOUT     10000L

volatile MQTTClient client;
volatile char* sensor_path = "your_sensor_path";

void handle_signal(int signal) {
    printf("Cleaning up and exiting...\n");
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    exit(0);
}

int main(int argc, char* argv[]) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int fd;
    char buf[10];

    MQTTClient_create(&client, ADDRESS, CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((fd = open(sensor_path, O_RDONLY)) == -1) {
        perror("Error opening sensor file");
        return 1;
    }

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        printf("Failed to connect to broker\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    pubmsg.payload = PAYLOAD;
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    while (1) {
        if (read(fd, buf, sizeof(buf)) == -1) {
            perror("Error reading from sensor");
            return 1;
        }

        pubmsg.payload = buf;

        if (MQTTClient_publishMessage(client, TOPIC, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
            printf("Failed to publish message\n");
            return 1;
        }

        printf("Waiting for up to %d seconds for publication of %s\n"
                "on topic %s for client with ClientID: %s\n",
                (int)(TIMEOUT/1000), pubmsg.payload, TOPIC, CLIENTID);
        MQTTClient_waitForCompletion(client, token, TIMEOUT);
    }

    return 0;
}

