#include <stdio.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_TRIG 23
#define GPIO_ECHO 24

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int request_flags = 0;
    int value;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed\n");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIG);
    echo = gpiod_chip_get_line(chip, GPIO_ECHO);

    if (!trig || !echo) {
        perror("Get line failed\n");
        return 1;
    }

    if (gpiod_line_request_output(trig, "trigger", request_flags) < 0) {
        perror("Request line as output failed\n");
        return 1;
    }

    if (gpiod_line_request_input(echo, "echo") < 0) {
        perror("Request line as input failed\n");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        while (1) {
            value = gpiod_line_get_value(echo);
            if (value == 1)
                break;
            usleep(1);
        }

        unsigned long start_time = ustime();
        while (1) {
            value = gpiod_line_get_value(echo);
            if (value == 0)
                break;
            usleep(1);
        }
        unsigned long travel_time = ustime() - start_time;

        double distance = (travel_time / 2.0) / 29.1;
        printf("Distance: %.2f cm\n", distance);

        usleep(200000);  // Wait for 0.2 seconds
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

    return 0;
}

