#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"

int fd;
struct termios oldtio, newtio;

void handle_exit(int sig) {
    tcsetattr(fd, TCSANOW, &oldtio);
    close(fd);
    exit(0);
}

int main() {
    char buf[255];
    int n;

    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY);
    if (fd < 0) {
        perror("Unable to open serial port");
        return 1;
    }

    tcgetattr(fd, &oldtio);
    bzero(&newtio, sizeof(newtio));

    newtio.c_cflag = B9600 | CRTSCTS | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;

    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &newtio);

    signal(SIGINT, handle_exit);

    while(1) {
        n = read(fd, buf, sizeof(buf));
        if (n > 0) {
            buf[n] = 0;
            printf("%s", buf);
        }
    }

    return 0;
}

#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <unistd.h>

#define MPU6050_I2C_ADDR 0x68

int main(void)
{
    int fd;
    int result;
    short gyroX, gyroY, gyroZ, accelX, accelY, accelZ;

    // Initialize wiringPi and I2C
    wiringPiSetup();
    fd = wiringPiI2CSetup(MPU6050_I2C_ADDR);
    if (fd < 0)
    {
        printf("Failed to initialize I2C: %d\n", fd);
        return 1;
    }

    // Initialize the MPU6050
    result = wiringPiI2CWriteReg8(fd, 0x6B, 0x80); // PWR_MGMT_1: Reset the device
    usleep(10000); // Wait for 10ms for the device to boot up
    wiringPiI2CWriteReg8(fd, 0x1B, 0x00); // GYRO_CONFIG: Set the full scale range to 250 degrees/sec
    wiringPiI2CWriteReg8(fd, 0x1C, 0x10); // ACCEL_CONFIG: Set the full scale range to 2g

    while (1)
    {
        // Read the gyroscope and accelerometer data
        gyroX = wiringPiI2CReadReg16(fd, 0x43);
        gyroY = wiringPiI2CReadReg16(fd, 0x45);
        gyroZ = wiringPiI2CReadReg16(fd, 0x47);
        accelX = wiringPiI2CReadReg16(fd, 0x3B);
        accelY = wiringPiI2CReadReg16(fd, 0x3D);
        accelZ = wiringPiI2CReadReg16(fd, 0x3F);

        // Print the data
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyroX, gyroY, gyroZ);
        printf("Accel: X=%d, Y=%d, Z=%d\n", accelX, accelY, accelZ);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    return 0;
}

