#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <MQTTClient.h>

#define ADDRESS     "your_broker_address"
#define CLIENTID    "ExampleClientPub"
#define TOPIC       "your_topic"
#define PAYLOAD     "Hello World!"
#define QOS         1
#define TIMEOUT     10000L

volatile MQTTClient client;

void handle_signal(int signal) {
    printf("Caught signal %d\n", signal);
    MQTTClient_disconnect(client, 1000);
    exit(0);
}

int main(int argc, char* argv[]) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    MQTTClient_create(&client, ADDRESS, CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        printf("Failed to connect, return code %d\n", rc);
        exit(-1);
    }

    signal(SIGINT, handle_signal);

    pubmsg.payload = PAYLOAD;
    pubmsg.payloadlen = strlen(PAYLOAD);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    while(1) {
        FILE* file = fopen("/path/to/sensor", "r");
        if (file == NULL) {
            printf("Failed to open sensor file\n");
            exit(-1);
        }

        char sensor_reading[256];
        fgets(sensor_reading, sizeof(sensor_reading), file);
        fclose(file);

        pubmsg.payload = sensor_reading;
        pubmsg.payloadlen = strlen(sensor_reading);

        MQTTClient_publishMessage(client, TOPIC, &pubmsg, &token);
        printf("Waiting for up to %d seconds for publication of %s\n"
                "on topic %s for client with ClientID: %s\n",
                (int)(TIMEOUT/1000), pubmsg.payload, TOPIC, CLIENTID);
        rc = MQTTClient_waitForCompletion(client, token, TIMEOUT);
        printf("Message with delivery token %d delivered\n", token);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    return rc;
}

