    struct v4l2_buffer buf;
    unsigned char *buffer_start;
    unsigned int buffer_length;

    // Open the camera device
    camera_fd = open(CAMERA_DEVICE, O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Open the output file
    output_fd = open(OUTPUT_FILE, O_WRONLY | O_CREAT, 0644);
    if (output_fd < 0) {
        perror("Failed to open output file");
        close(camera_fd);
        return 1;
    }

    // Initialize buffer information
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    // Query buffer information
    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer information");
        close(output_fd);
        close(camera_fd);
        return 1;
    }

    // Map the buffer into memory
    buffer_start = mmap(NULL, buf.length, PROT_READ, MAP_SHARED, camera_fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("Failed to map buffer into memory");
        close(output_fd);
        close(camera_fd);
        return 1;
    }

    // Write the buffer to the output file
    write(output_fd, buffer_start, buf.length);

    // Clean up
    munmap(buffer_start, buf.length);
    close(output_fd);
    close(camera_fd);

    return 0;
}

