#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mqtt.h>

#define MQTT_BROKER "mqtt://your_broker_address"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000

#define MCP3008_CMD 0x01

void on_connect(struct mqtt_client_t *client, void *obj, int reason_code) {
    printf("Connected to the broker\n");
}

void on_disconnect(struct mqtt_client_t *client, void *obj, int reason_code) {
    printf("Disconnected from the broker\n");
}

int main() {
    struct mqtt_client_t client;
    struct mqtt_connect_options_t conn_opts;
    struct mqtt_message_t msg;
    struct mqtt_response_t res;
    int rc;
    int fd;
    uint8_t data[3];
    uint16_t adc_val;

    // Initialize wiringPi and SPI
    if (wiringPiSetup() == -1) {
        printf("Failed to initialize wiringPi\n");
        return 1;
    }

    fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd == -1) {
        printf("Failed to initialize SPI\n");
        return 1;
    }

    // Initialize MQTT client
    mqtt_client_init(&client, MQTT_BROKER, MQTT_PORT, on_connect, on_disconnect, NULL);

    mqtt_connect_options_init(&conn_opts);
    rc = mqtt_connect(&client, &conn_opts, &res);
    if (rc != MQTT_OK) {
        printf("Failed to connect to the broker\n");
        return 1;
    }

    // Read data from the MCP3008 and publish it to the MQTT broker
    data[0] = MCP3008_CMD;
    data[1] = 0x80;  // Start bit and single-ended mode
    data[2] = 0x00;

    while (1) {
        wiringPiSPIDataRW(SPI_CHANNEL, data, 3);

        adc_val = (data[1] << 8) | data[2];
        printf("ADC value: %d\n", adc_val);

        msg.payload = (void*)&adc_val;
        msg.payloadlen = sizeof(adc_val);
        msg.qos = 0;
        msg.retained = 0;

        rc = mqtt_publish(&client, MQTT_TOPIC, &msg, &res);
        if (rc != MQTT_OK) {
            printf("Failed to publish message\n");
            break;
        }

        sleep(1);
    }

    // Disconnect from the MQTT broker
    mqtt_disconnect(&client, &res);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int camera_fd, image_fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer;
    int buffer_length;

    // Open camera device
    camera_fd = open(CAMERA_DEVICE, O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        return 1;
    }

    // Check if device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        return 1;
    }

    // Set image format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set image format");
        return 1;
    }

    // Allocate buffer for image
    buffer_length = fmt.fmt.pix.sizeimage;
    buffer = malloc(buffer_length);
    if (!buffer) {
        perror("Failed to allocate buffer for image");
        return 1;
    }

    // Capture image
    if (read(camera_fd, buffer, buffer_length) < 0) {
        perror("Failed to capture image");
        return 1;
    }

    // Save image to file
    image_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT, 0644);
    if (image_fd < 0) {
        perror("Failed to open image file");
        return 1;
    }
    if (write(image_fd, buffer, buffer_length) < 0) {
        perror("Failed to write image to file");
        return 1;
    }
    close(image_fd);

    // Clean up
    free(buffer);
    close(camera_fd);

    return 0;
}

