    if ((file_i2c = open(I2C_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus: %s\n", strerror(errno));
        exit(1);
    }

    // Set the I2C slave address
    if (ioctl(file_i2c, I2C_SLAVE, I2C_ADDRESS) < 0) {
        printf("Failed to acquire bus access or talk to slave: %s\n", strerror(errno));
        exit(1);
    }

    // Main loop
    while (1) {
        // Read from the PCF8574
        length = read(file_i2c, buffer, 1);
        if (length != 1) {
            printf("Failed to read from the i2c bus: %s\n", strerror(errno));
            exit(1);
        }

        // Print the read value
        printf("Read value: 0x%02X\n", buffer[0]);

        // Sleep for 0.5 seconds
        sleep(0.5);
    }

    // Close the I2C device
    close(file_i2c);

    return 0;
}

