#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>
#include <time.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)

int main() {
    int camera_fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    void *mem_start;
    int i;
    char image_name[20];
    FILE *fp;

    // Open the camera device
    if ((camera_fd = open(CAMERA_DEVICE, O_RDWR)) < 0) {
        perror("Cannot open camera device");
        return 1;
    }

    // Check if the device supports video capture
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Cannot query device capabilities");
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        perror("Device does not support video capture");
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Cannot set image format");
        return 1;
    }

    // Request buffers
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &buf) < 0) {
        perror("Cannot request buffers");
        return 1;
    }

    // Map the buffers
    mem_start = mmap(NULL, IMAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (mem_start == MAP_FAILED) {
        perror("Cannot map buffers");
        return 1;
    }

    // Start capturing images
    for (i = 0; ; i++) {
        // Capture an image
        if (ioctl(camera_fd, VIDIOC_STREAMON, &buf.type) < 0) {
            perror("Cannot start capturing images");
            return 1;
        }

        // Save the image to a file
        sprintf(image_name, "image%d.ppm", i);
        if ((fp = fopen(image_name, "wb")) == NULL) {
            perror("Cannot open file for writing");
            return 1;
        }

        fprintf(fp, "P6\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        fwrite(mem_start, 1, IMAGE_SIZE, fp);
        fclose(fp);

        // Stop capturing images
        if (ioctl(camera_fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
            perror("Cannot stop capturing images");
            return 1;
        }

        // Sleep for 0.1 seconds
        struct timespec ts = {0, 100000000};
        nanosleep(&ts, NULL);
    }

    // Clean up
    munmap(mem_start, IMAGE_SIZE);
    close(camera_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 500

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the GPIO mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Start the PWM output
    if (gpioStartPWM(GPIO_PIN, PWM_FREQ, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("PWM output on GPIO %d started\n", GPIO_PIN);

    // Wait for 5 seconds
    time_sleep(5);

    // Stop the PWM output
    gpioStopPWM(GPIO_PIN);

    printf("PWM output on GPIO %d stopped\n", GPIO_PIN);

    // Terminate the library
    gpioTerminate();

    return 0;
}

