#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_TRIG 17
#define GPIO_ECHO 18

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int request_flags = 0;
    int value;
    long long timeout_ns = 100000000; // 100ms
    struct timespec timeout = {0, timeout_ns};

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed\n");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIG);
    if (!trig) {
        perror("Get line failed\n");
        return 1;
    }

    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo) {
        perror("Get line failed\n");
        return 1;
    }

    value = gpiod_line_request_output(trig, "HC-SR04", request_flags);
    if (value < 0) {
        perror("Request line as output failed\n");
        return 1;
    }

    value = gpiod_line_request_input(echo, "HC-SR04");
    if (value < 0) {
        perror("Request line as input failed\n");
        return 1;
    }

    // Send trigger signal
    value = gpiod_line_set_value(trig, 1);
    if (value < 0) {
        perror("Set line value failed\n");
        return 1;
    }
    usleep(10);
    value = gpiod_line_set_value(trig, 0);
    if (value < 0) {
        perror("Set line value failed\n");
        return 1;
    }

    // Wait for echo signal
    value = gpiod_line_event_wait(echo, &timeout);
    if (value < 0) {
        perror("Wait for event failed\n");
        return 1;
    }

    // Read echo signal
    value = gpiod_line_get_value(echo);
    if (value < 0) {
        perror("Get line value failed\n");
        return 1;
    }

    printf("Distance: %d cm\n", value);

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);

