#include <stdio.h>
#include <stdlib.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>

#define SHT31_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

int main() {
    int file_i2c;
    int length;
    unsigned char buffer[6];
    float temp, humidity;

    if ((file_i2c = open(I2C_DEV, O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file_i2c, I2C_SLAVE, SHT31_ADDR) < 0) {
        printf("Failed to acquire bus access or talk to slave\n");
        exit(1);
    }

    while (1) {
        // Send measurement command
        buffer[0] = 0x2C;
        buffer[1] = 0x06;
        if (write(file_i2c, buffer, 2) != 2) {
            printf("Failed to send measurement command\n");
            exit(1);
        }

        sleep(1);

        // Read 6 bytes of data
        if ((length = read(file_i2c, buffer, 6)) != 6) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        // Calculate temperature and humidity
        temp = buffer[0] * 256 + buffer[1];
        temp /= 65535;
        temp *= 175;
        temp -= 45;

        humidity = buffer[3] * 256 + buffer[4];
        humidity /= 65535;
        humidity *= 100;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        sleep(5);
    }

    close(file_i2c);
    return 0;
}

