#define GPIO_PWM_PIN3 22
#define GPIO_PWM_PIN4 27

#define PWM_FREQUENCY 1000
#define PWM_DUTYCYCLE 500

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_PIN1, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Unable to set GPIO %d mode\n", GPIO_PWM_PIN1);
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_PIN2, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Unable to set GPIO %d mode\n", GPIO_PWM_PIN2);
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_PIN3, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Unable to set GPIO %d mode\n", GPIO_PWM_PIN3);
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_PIN4, PI_OUTPUT) < 0)
    {
        fprintf(stderr, "Unable to set GPIO %d mode\n", GPIO_PWM_PIN4);
        return 1;
    }

    if (gpioPWM(GPIO_PWM_PIN1, PWM_FREQUENCY, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Unable to start PWM on GPIO %d\n", GPIO_PWM_PIN1);
        return 1;
    }

    if (gpioPWM(GPIO_PWM_PIN2, PWM_FREQUENCY, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Unable to start PWM on GPIO %d\n", GPIO_PWM_PIN2);
        return 1;
    }

    if (gpioPWM(GPIO_PWM_PIN3, PWM_FREQUENCY, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Unable to start PWM on GPIO %d\n", GPIO_PWM_PIN3);
        return 1;
    }

    if (gpioPWM(GPIO_PWM_PIN4, PWM_FREQUENCY, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Unable to start PWM on GPIO %d\n", GPIO_PWM_PIN4);
        return 1;
    }

    printf("PWM output on GPIO %d, %d, %d, %d started\n", GPIO_PWM_PIN1, GPIO_PWM_PIN2, GPIO_PWM_PIN3, GPIO_PWM_PIN4);

    gpioTerminate();

    return 0;
}

