#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int camera_fd, image_fd;
    unsigned char *buffer;
    struct v4l2_buffer buf;
    struct v4l2_capability cap;

    // Open camera device
    camera_fd = open(CAMERA_DEVICE, O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Check if device is present
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        return 1;
    }

    // Open image file
    image_fd = open(IMAGE_FILE, O_WRONLY | O_CREAT, 0644);
    if (image_fd < 0) {
        perror("Failed to open image file");
        return 1;
    }

    // Allocate buffer
    buffer = malloc(cap.capabilities & V4L2_CAP_STREAMING ? 1 : 0);
    if (!buffer) {
        perror("Failed to allocate buffer");
        return 1;
    }

    // Capture image
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return 1;
    }

    // Write image to file
    if (write(image_fd, buffer, buf.bytesused) < 0) {
        perror("Failed to write image to file");
        return 1;
    }

    // Clean up
    free(buffer);
    close(image_fd);
    close(camera_fd);

    return 0;
}

