#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>

#define GPIO_PIN 18
#define DELAY_TIME_MS 5

void setColor(int r, int g, int b) {
    gpioWrite(GPIO_PIN, r);
    gpioDelay(1);
    gpioWrite(GPIO_PIN, g);
    gpioDelay(1);
    gpioWrite(GPIO_PIN, b);
    gpioDelay(1);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    for (int i = 0; i < 3; i++) {
        // Set the LED to red
        setColor(1, 0, 0);
        gpioDelay(DELAY_TIME_MS * 1000);

        // Set the LED to green
        setColor(0, 1, 0);
        gpioDelay(DELAY_TIME_MS * 1000);

        // Set the LED to blue
        setColor(0, 0, 1);
        gpioDelay(DELAY_TIME_MS * 1000);

        // Set the LED to off
        setColor(0, 0, 0);
        gpioDelay(DELAY_TIME_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

