#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN_4 4
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18

int main(void)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the GPIO modes
    gpioSetMode(GPIO_PIN_4, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_17, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_18, PI_OUTPUT);

    // Start the PWM on the GPIO pins
    gpioPWM(GPIO_PIN_4, 500);
    gpioPWM(GPIO_PIN_17, 500);
    gpioPWM(GPIO_PIN_18, 500);

    // Main loop
    while (1)
    {
        // Print the state of the GPIO pins
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d\n", gpioRead(GPIO_PIN_4), gpioRead(GPIO_PIN_17), gpioRead(GPIO_PIN_18));

        // Sleep for 0.1 seconds
        time_sleep(0.1);
    }

    // Cleanup
    gpioPWM(GPIO_PIN_4, 0);
    gpioPWM(GPIO_PIN_17, 0);
    gpioPWM(GPIO_PIN_18, 0);
    gpioTerminate();

    return 0;
}

