#include <stdio.h>
#include <pigpio.h>

#define GPIO_PIN_4 4
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_27 27

#define PWM_FREQUENCY 1000
#define PWM_DUTYCYCLE 50
#define PWM_CYCLES 5
#define PWM_PERIOD 60

int main(void)
{
    int i, j;

    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the GPIO modes
    gpioSetMode(GPIO_PIN_4, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_17, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_18, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_27, PI_OUTPUT);

    // Start the PWM signals
    gpioPWM(GPIO_PIN_4, PWM_FREQUENCY, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PIN_17, PWM_FREQUENCY, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PIN_18, PWM_FREQUENCY, PWM_DUTYCYCLE);
    gpioPWM(GPIO_PIN_27, PWM_FREQUENCY, PWM_DUTYCYCLE);

    // Run the PWM for 5 cycles of 60 seconds each
    for (i = 0; i < PWM_CYCLES; i++)
    {
        printf("Starting cycle %d\n", i + 1);
        for (j = 0; j < PWM_PERIOD; j++)
        {
            sleep(1);
            printf("Elapsed time: %ds\n", j + 1);
        }
        printf("End of cycle %d\n", i + 1);
    }

    // Stop the PWM signals
    gpioPWM(GPIO_PIN_4, 0, 0);
    gpioPWM(GPIO_PIN_17, 0, 0);
    gpioPWM(GPIO_PIN_18, 0, 0);
    gpioPWM(GPIO_PIN_27, 0, 0);

    // Terminate the library
    gpioTerminate();

    return 0;
}

