#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PWM_PIN 17
#define PWM_FREQUENCY 1000
#define PWM_DUTYCYCLE 500

int main(int argc, char **argv)
{
    // Initialize the library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the GPIO mode
    gpioSetMode(GPIO_PWM_PIN, PI_OUTPUT);

    // Start the PWM output
    if (gpioStartPWM(GPIO_PWM_PIN, PWM_FREQUENCY, PWM_DUTYCYCLE) < 0)
    {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PWM_PIN);
        gpioTerminate();
        return 1;
    }

    // Print the state to standard output
    printf("PWM output on GPIO %d started with frequency %d and duty cycle %d\n", GPIO_PWM_PIN, PWM_FREQUENCY, PWM_DUTYCYCLE);

    // Wait for user interrupt
    while (1)
    {
        sleep(0.05);
    }

    // Cleanup
    gpioStopPWM(GPIO_PWM_PIN);
    gpioTerminate();

    return 0;
}

