    gpioSetMode(GPIO_PWM1, PI_OUTPUT);
    gpioSetMode(GPIO_PWM2, PI_OUTPUT);
    gpioSetMode(GPIO_PWM3, PI_OUTPUT);

    // Start the PWM output
    gpioPWM(GPIO_PWM1, 500); // 500Hz
    gpioPWM(GPIO_PWM2, 500); // 500Hz
    gpioPWM(GPIO_PWM3, 500); // 500Hz

    // Loop until the program is interrupted
    while (1)
    {
        // Change the duty cycle of the PWM output
        gpioPWM(GPIO_PWM1, (rand() % 2000) + 500); // Random duty cycle between 0.5 and 2.5 seconds
        gpioPWM(GPIO_PWM2, (rand() % 2000) + 500); // Random duty cycle between 0.5 and 2.5 seconds
        gpioPWM(GPIO_PWM3, (rand() % 2000) + 500); // Random duty cycle between 0.5 and 2.5 seconds

