#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

#define MAX31855_SPI_DEVICE "/dev/spidev0.0"
#define MAX31855_SPI_SPEED 1000000
#define MAX31855_CS_PIN 0

int main(int argc, char **argv) {
    int fd;
    unsigned char tx_buf[3] = {0};
    unsigned char rx_buf[3] = {0};
    struct spi_ioc_transfer spi;

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    pinMode(MAX31855_CS_PIN, OUTPUT);
    digitalWrite(MAX31855_CS_PIN, HIGH);

    if ((fd = open(MAX31855_SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &MAX31855_SPI_SPEED) == -1) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        return 1;
    }

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx_buf;
    spi.rx_buf = (unsigned long)rx_buf;
    spi.len = 3;
    spi.delay_usecs = 0;
    spi.speed = MAX31855_SPI_SPEED;
    spi.bits_per_word = 8;

    digitalWrite(MAX31855_CS_PIN, LOW);
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi) == -1) {
        fprintf(stderr, "Failed to send SPI message: %s\n", strerror(errno));
        return 1;
    }
    digitalWrite(MAX31855_CS_PIN, HIGH);

    printf("Temperature: %.2f\n", (rx_buf[0] << 8 | rx_buf[1]) / 32.0);

    close(fd);
    return 0;
}

