#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_TRIG 4
#define GPIO_ECHO 17

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int request_flags = 0;
    int timeout_ms = 1000;
    int ret, val;
    long long start_time, end_time;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed\n");
        return -1;
    }

    trig = gpiod_chip_get_line(chip, GPIO_TRIG);
    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!trig || !echo) {
        perror("Get line failed\n");
        return -1;
    }

    ret = gpiod_line_request_output(trig, "trigger", request_flags);
    if (ret < 0) {
        perror("Request line as output failed\n");
        return -1;
    }

    ret = gpiod_line_request_input(echo, "echo");
    if (ret < 0) {
        perror("Request line as input failed\n");
        return -1;
    }

    val = 0;
    ret = gpiod_line_set_value(trig, val);
    if (ret < 0) {
        perror("Set line value failed\n");
        return -1;
    }

    usleep(2);

    val = 1;
    ret = gpiod_line_set_value(trig, val);
    if (ret < 0) {
        perror("Set line value failed\n");
        return -1;
    }

    usleep(10);

    val = 0;
    ret = gpiod_line_set_value(trig, val);
    if (ret < 0) {
        perror("Set line value failed\n");
        return -1;
    }

    start_time = gpiod_line_event_wait(echo, timeout_ms);
    if (start_time < 0) {
        perror("Wait for event failed\n");
        return -1;
    }

