    {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    while (1)
    {
        gpioPWM(GPIO_PIN, PWM_FREQ, dutyCycle * PWM_FREQ / PWM_RANGE);

        printf("Duty cycle: %d%%\n", dutyCycle);

        if (dutyCycle == PWM_RANGE || dutyCycle == 0)
        {
            direction = -direction;
        }

