    struct gpiod_chip *chip;
    struct gpiod_line *trigger, *echo;
    int request_flags = 0;
    int timeout_ms = 1000;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Open chip failed\n");
        return -1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("Get line failed\n");
        return -1;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("Get line failed\n");
        return -1;
    }

    ret = gpiod_line_request_output(trigger, "trigger", request_flags);
    if (ret < 0) {
        perror("Request line as output failed\n");
        return -1;
    }

    ret = gpiod_line_request_input(echo, "echo");
    if (ret < 0) {
        perror("Request line as input failed\n");
        return -1;
    }

    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        perror("Set line value failed\n");
        return -1;
    }

    usleep(10);

    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        perror("Set line value failed\n");
        return -1;
    }

    ret = gpiod_line_event_wait_timeout(echo, 0, timeout_ms);
    if (ret < 0) {
