    if (!line) {
        perror("Get line failed\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(line, "gpio-example", 0) < 0) {
        perror("Request line as output failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set GPIO to HIGH
    value = 1;
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Set line value failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Print the state
    printf("GPIO %d is %s\n", GPIO_LINE, value ? "HIGH" : "LOW");

    // Set GPIO to LOW
    value = 0;
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Set line value failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Print the state
    printf("GPIO %d is %s\n", GPIO_LINE, value ? "HIGH" : "LOW");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTYCYCLE 500000

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    int pwm_handle = gpioStartPWM(GPIO_PIN, PWM_FREQ, PWM_DUTYCYCLE);

    if (pwm_handle < 0)
    {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("PWM signal on GPIO %d started\n", GPIO_PIN);

    while (1)
    {
        sleep(0.2);
    }

    gpioStopPWM(pwm_handle);
    gpioTerminate();

    return 0;
}

