#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define MPU6050_I2C_ADDR 0x68

int main(void)
{
    int fd;
    int result;
    short gyroX, gyroY, gyroZ;
    short accelX, accelY, accelZ;

    // Initialize wiringPi library
    if (wiringPiSetup() == -1)
    {
        printf("wiringPiSetup failed\n");
        return 1;
    }

    // Open I2C device
    fd = wiringPiI2CSetup(MPU6050_I2C_ADDR);
    if (fd == -1)
    {
        printf("wiringPiI2CSetup failed\n");
        return 1;
    }

    // Initialize MPU6050
    result = wiringPiI2CWriteReg8(fd, 0x6B, 0x80); // PWR_MGMT_1: Reset
    usleep(10000); // Wait for all registers to reset
    result = wiringPiI2CWriteReg8(fd, 0x1B, 0x00); // GYRO_CONFIG: Set full scale to 250
    result = wiringPiI2CWriteReg8(fd, 0x1C, 0x00); // ACCEL_CONFIG: Set full scale to 2

    while (1)
    {
        // Read gyroscope data
        gyroX = wiringPiI2CReadReg16(fd, 0x43);
        gyroY = wiringPiI2CReadReg16(fd, 0x45);
        gyroZ = wiringPiI2CReadReg16(fd, 0x47);

        // Read accelerometer data
        accelX = wiringPiI2CReadReg16(fd, 0x3B);
        accelY = wiringPiI2CReadReg16(fd, 0x3D);
        accelZ = wiringPiI2CReadReg16(fd, 0x3F);

        // Print readings
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyroX, gyroY, gyroZ);
        printf("Accel: X=%d, Y=%d, Z=%d\n", accelX, accelY, accelZ);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define DELAY_TIME 600000 // 0.6 seconds

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value = 0;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Open chip failed\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Get line failed\n");
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio-led-example", 0);
    if (ret < 0) {
        perror("Request line as output failed\n");
        return -1;
    }

    while (1) {
        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Set line value failed\n");
            return -1;
        }

        printf("Set GPIO %d value to %d\n", GPIO_LINE, value);
        usleep(DELAY_TIME);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}
